exercises.solution:
using System;

public class Program
{
    public static void Main()
    {
        Console.WriteLine(SomarDigitos(123));
        Console.WriteLine(SomarDigitos(9999));
    }

    static int SomarDigitos(int n)
    {
        int soma = 0;
        while (n > 0)
        {
            soma += n % 10;
            n /= 10;
        }
        return soma;
    }
}

