using System;
using System.Text;

public class Program
{
    public static void Main()
    {
        Console.WriteLine(Inverter("dotnet"));
    }

    static string Inverter(string s)
    {
        var sb = new StringBuilder(s.Length);
        for (int i = s.Length - 1; i >= 0; i--)
            sb.Append(s[i]);
        return sb.ToString();
    }
}

